preparation_powershell_not_executed:
$secure = Read-Host '输入细粒度PAT' -AsSecureString
$headers = @{
  Authorization = 'Bearer ' + [Net.NetworkCredential]::new('', $secure).Password
  Accept = 'application/vnd.github+json'
  'User-Agent' = 'Codespaces-readonly-check'
}
try {
  $base = 'https://api.github.com'
  (Invoke-RestMethod "$base/user" -Headers $headers).login
  $r = Invoke-RestMethod `
    "$base/repos/lzwislam-collab/doge-data-collector/codespaces?per_page=100" `
    -Headers $headers
  $r | Select-Object total_count
  $r.codespaces | Select-Object name, state, machine
}
finally {
  $headers.Clear()
  Remove-Variable secure, headers -ErrorAction SilentlyContinue
}
